import test from 'node:test';
import assert from 'node:assert/strict';
import {compareDraft, resolveDraft, discardDraft} from '../src/components/draft.js';
import {compareDraft as workCompare, resolveDraft as workResolve, discardDraft as workDiscard} from '../src/pages/work/issue-draft.js';
import {filterDraft, filterPayload} from '../src/pages/insight/search-state.js';
import {savedFilterInput} from '../../shared/src/index.js';
import {createPlanningScope} from '../src/pages/work/planning-actions.js';
import {createRequestGuard} from '../src/pages/insight/request-guard.js';

test('filter and work editors share the exact generic comparison exports', () => {
  assert.equal(workCompare, compareDraft); assert.equal(workResolve, resolveDraft); assert.equal(workDiscard, discardDraft);
  const base = filterDraft({name: 'Base', query: 'status:active'}, 'org');
  const mine = {...base, name: 'Mine'}, latest = {...base, description: 'Peer description', query: 'priority>=3'};
  const comparison = compareDraft(base, mine, latest);
  assert.equal(comparison.conflicts.length, 0);
  assert.deepEqual(resolveDraft(comparison), {...latest, name: 'Mine'});
});
test('each overlapping saved-filter field needs a deliberate mine/latest decision', () => {
  const base = filterDraft({name: 'Base', description: 'Before'}, 'org');
  const mine = {...base, name: 'Mine', description: 'Local'}, latest = {...base, name: 'Peer', description: 'Peer description'};
  const comparison = compareDraft(base, mine, latest);
  assert.deepEqual(comparison.conflicts.map(field => field.key), ['name', 'description']);
  assert.throws(() => resolveDraft(comparison, {name: 'mine'}), /description/);
  assert.deepEqual(resolveDraft(comparison, {name: 'mine', description: 'latest'}), {...latest, name: 'Mine'});
});
test('declining dirty discard retains the original filter values and clean cancel asks nothing', () => {
