test('current save admission excludes same-turn duplicates and abandonment suppresses completion', async () => {
  const scope = createPlanningScope(), first = scope.begin();
  assert.ok(first); assert.equal(scope.begin(), null);
  let published = 0, applied = 0, release;
  const response = new Promise(resolve => {release = resolve;});
  const operation = (async () => {published++; await response; if (first.current()) applied++;})();
  scope.dispose(); release(); await operation;
  assert.equal(first.signal.aborted, true); assert.equal(published, 1); assert.equal(applied, 0); assert.equal(scope.begin(), null);
});
